import { resolveClubParametersId } from './clubs/clubRepository'

/**
 * Stable gameplay living bases approved 2026-10-23, not actual player residences
 * or claims of exclusive municipal/official hometowns. Source facts and authored
 * choices are intentionally separate. Full audit: approved-city-map.json and
 * cloud-strategy-protocol.md §3 in the FUN-V3 evidence bundle.
 */
export type ClubCitySourceKind = 'official' | 'secondary' | 'repository' | 'game-design'
export type ClubCityMappingBasis = 'SOURCED_HOME_CITY' | 'PRODUCT_HOME_BASE' | 'PRODUCT_CANON' | 'UNKNOWN'

export interface ClubCitySource {
  readonly kind: ClubCitySourceKind
  readonly url: string
}

export interface ClubCityResolution {
  readonly canonicalClubId: string | null
  readonly cityId: string | null
  readonly cityName: string | null
  readonly geographicCountryCode: string | null
  /** Product exceptions remain game-design even when the underlying facts are official. */
  readonly kind: ClubCitySourceKind | 'unknown'
  readonly sourceKind: ClubCityMappingBasis
  readonly sources: readonly ClubCitySource[]
  readonly decisionSource: string | null
  readonly rationale: string
}

export interface ClubCityRecord extends ClubCityResolution {
  readonly canonicalClubId: string
  readonly cityId: string
  readonly cityName: string
  readonly geographicCountryCode: string
  readonly sourceKind: Exclude<ClubCityMappingBasis, 'UNKNOWN'>
}

