export const CLUB_CITY_RECORDS: readonly ClubCityRecord[] = Object.freeze(CITY_ROWS.map((row) => {
  const [canonicalClubId, cityId, cityName, geographicCountryCode, sourceKind, sourceIndexes, rationale] = row
  const sources = sourceIndexes.map((index) => SOURCE_REGISTRY[index]!)
  const kind: ClubCitySourceKind = sourceKind === 'SOURCED_HOME_CITY'
    ? sources.some((source) => source.kind === 'official') ? 'official' : 'secondary'
    : 'game-design'
  if (kind === 'game-design') sources.push(PRODUCT_DECISION_SOURCE)
  return Object.freeze({
    canonicalClubId, cityId, cityName, geographicCountryCode, kind, sourceKind,
    sources: Object.freeze(sources), decisionSource: PRODUCT_DECISION_SOURCE.url, rationale,
  })
}))

const citiesByClubId: ReadonlyMap<string, ClubCityRecord> = new Map(
  CLUB_CITY_RECORDS.map((record) => [record.canonicalClubId, record]),
)
const knownCityIds: ReadonlySet<string> = new Set(CLUB_CITY_RECORDS.map((record) => record.cityId))
const UNKNOWN_CLUB_CITY: ClubCityResolution = Object.freeze({
  canonicalClubId: null, cityId: null, cityName: null, geographicCountryCode: null,
  kind: 'unknown', sourceKind: 'UNKNOWN', sources: Object.freeze([]), decisionSource: null,
  rationale: 'Unrecognized club ID. No living city or move can be inferred.',
})

/** Accept exact canonical/runtime or workbook IDs through the shared catalog resolver. */
export function resolveClubCity(clubId: string | null | undefined): ClubCityResolution {
  if (typeof clubId !== 'string') return UNKNOWN_CLUB_CITY
  const canonicalId = resolveClubParametersId(clubId)
  if (!canonicalId) return UNKNOWN_CLUB_CITY
  return citiesByClubId.get(canonicalId) ?? Object.freeze({
    ...UNKNOWN_CLUB_CITY,
    canonicalClubId: canonicalId,
    rationale: 'Known club without an approved living base. No city or move can be inferred.',
  })
}

export function isKnownLivingCityId(cityId: unknown): cityId is string {
  return typeof cityId === 'string' && knownCityIds.has(cityId)
}
